export function renderOperationContext(context: OperationContext, options: SpecificationReportOptions = {}): string {
  if (options.format !== undefined && !['html', 'markdown'].includes(options.format)) throw new ClearingsError('INVALID_ARGUMENTS', 'Specification reports support html and markdown.');
  const root = context.operations[0]!;
  const scenarios = options.scenarios ?? [];
  for (const scenario of scenarios) if (scenario.result.artifact_id !== context.artifact_id || scenario.result.operation_id !== scenario.operation_id || !context.operations.some(operation => operation.id === scenario.operation_id)) throw new ClearingsError('INVALID_SELECTION', 'Report scenarios must belong to included operations in this specification.');
  const status = `${context.perspective === 'intended' ? 'Proposed intended behavior' : 'Proposed source interpretation'}. ${context.operations.length} operations. Source hashes checked; source authenticity and claim support are not established.`;
  if (options.format !== 'html') {
    return [`# ${md(root.name)}`, '', md(root.purpose), '', status, '', `Specification: \`${context.artifact_id}\`.`, '',
      '## A concrete case', '', ...(scenarios.length ? scenarios.flatMap(scenario => [`### ${md(scenario.name)}`, '', `Operation: \`${scenario.operation_id}\`. Scenario check: **${scenario.result.verdict}**.`, '', '<details>', '<summary>Open inputs, outcome, and checks</summary>', '', fence({ observation: scenario.observation, result: scenario.result }), '', '</details>', '']) : ['Inspect the conditions below to find the outcome for your case.', '']),
      ...(context.states.length ? ['## State used by these rules', '', '| State | Type | Meaning |', '| --- | --- | --- |', ...context.states.map(state => `| ${md(state.name)} | ${md(typeName(state.type))} | ${md(state.description)} |`), ''] : []),
      ...context.operations.flatMap(operation => [`<a id="${anchor(operation.id)}"></a>`, `## ${md(operation.name)}`, '', md(operation.purpose), '',
        '| Condition | Outcome | Required result |', '| --- | --- | --- |', ...operation.outcomes.map(outcome => `| ${md(formatExpression(outcome.when))} | ${md(outcome.description)} | ${md(outcome.ensures.map(rule => rule.description).join(' '))} |`), '',
        ...operation.guarantees.map(rule => `- ${md(rule.description)}`), '',
        ...(operation.implementations.length ? ['| Implementation | Responsibility |', '| --- | --- |', ...operation.implementations.map(item => `| ${md(item.name)} | ${md(item.responsibility)} |`), ''] : []),
        ...operation.decisions.map(item => `- **${item.disposition}${item.blocking ? '; blocking' : ''}:** ${md(item.question)} ${md(item.consequence)}`), '',
        '<details>', '<summary>Types, state, effects, and exact rules</summary>', '', fence(operation), '', '</details>', '']),
      '## Relationships', '', 'These are declared dependencies. The labels state their purpose; they are not an execution trace.', '', '| From | Target | Relationship | Role |', '| --- | --- | --- | --- |',
      ...context.links.map(link => `| ${md(context.operations.find(operation => operation.id === link.from_id)!.name)} | ${md(link.target_name ?? link.to_id)} | ${md(link.kind)} | ${md(link.role)}${link.included ? '' : ' (deferred)'} |`), '',
      '## Source and design evidence', '', ...context.sources.flatMap(source => [`<a id="${anchor(source.id)}"></a>`, '<details>', `<summary>${md(source.locator)}</summary>`, '', `Origin: ${source.origin}. SHA-256: \`${source.sha256}\`.`, '', codeFence(source.text).replace('typescript\n', source.origin === 'source' ? 'typescript\n' : 'text\n'), '', '</details>', '']),
      '## Context scope', '', `${context.budget.used_bytes} UTF-8 bytes in the canonical JSON package. Text rendering has a different size.`, '', fence(context.omissions), '', md(context.retrieval), '', 'Scenario checks evaluate supplied observations. They do not prove the implementation or authenticate requirements.', ''].join('\n');
  }
  const evidenceLinks = (ids: string[]) => ids.map(id => `<a href="#${anchor(id)}">Source</a>`).join(' · ');
  const checkView = (scenario: CheckedScenario) => `<details class="scenario"><summary>${h(scenario.name)} <span class="tag">${h(scenario.result.verdict)}</span></summary><p>Operation: ${h(scenario.operation_id)}. This checks supplied observations against the model.</p><pre tabindex="0" aria-label="Scenario inputs and outcome"><code>${h(JSON.stringify(scenario.observation, null, 2))}</code></pre><ul>${scenario.result.checks.map(check => `<li><strong>${h(check.verdict)}</strong> — ${h(check.description)}${check.reason ? ` ${h(check.reason)}` : ''}</li>`).join('')}</ul><p>${h(scenario.result.limitations.join(' '))}</p></details>`;
  return `<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${h(root.name)} · Clearings</title><style>${REPORT_CSS}
