${operation.guarantees.length ? `<ul>${operation.guarantees.map(rule => `<li>${h(rule.description)} ${evidenceLinks(rule.evidence_ids)}</li>`).join('')}</ul>` : ''}
${operation.implementations.length ? `<h4>Which implementation contributes?</h4><div class="table-wrap" tabindex="0" aria-label="Implementation responsibilities"><table><thead><tr><th>Implementation</th><th>Responsibility</th></tr></thead><tbody>${operation.implementations.map(item => `<tr><td>${h(item.name)}</td><td>${h(item.responsibility)} ${evidenceLinks(item.evidence_ids)}</td></tr>`).join('')}</tbody></table></div>` : ''}
${operation.decisions.length ? `<h4>Open boundaries</h4><ul>${operation.decisions.map(item => `<li><strong>${h(item.question)}</strong> ${h(item.consequence)} <span class="tag">${h(item.disposition)}${item.blocking ? '; blocking' : ''}</span></li>`).join('')}</ul>` : ''}
<details><summary>Types, state, and canonical operation</summary><p>Inputs: ${h(Object.entries(operation.inputs).map(([name, type]) => `${name}: ${typeName(type)}`).join('; ') || 'none')}.</p><p>Output: ${h(typeName(operation.output))}. State frame: ${h(operation.frame)}. Effect boundary: ${h(operation.effects.completeness)}.</p><pre tabindex="0" aria-label="Canonical operation JSON"><code>${h(JSON.stringify(operation, null, 2))}</code></pre></details></article>`).join('')}</section>
<section id="relationships"><h2>Relationships</h2><p>These are declared dependencies. Their roles do not establish an observed execution order.</p><div class="table-wrap" tabindex="0" aria-label="Operation relationships"><table><thead><tr><th>From</th><th>Target</th><th>Role</th></tr></thead><tbody>${context.links.map(link => `<tr><td>${h(context.operations.find(operation => operation.id === link.from_id)!.name)}</td><td>${link.included ? `<a href="#${anchor(link.to_id)}">${h(link.target_name!)}</a>` : h(link.target_name ?? link.to_id)}<br><span class="tag">${h(link.kind)}${link.included ? '' : '; deferred'}</span></td><td>${h(link.role)}</td></tr>`).join('')}</tbody></table></div></section>
<section id="evidence"><h2>Source and design evidence</h2><p>Attached text is exact. A valid hash establishes content integrity. Source authenticity, claim support, and requirement acceptance need separate checks.</p>${context.sources.map(source => `<details id="${anchor(source.id)}"><summary>${h(source.locator)}</summary><p>${h(source.origin)} · ${h(source.sha256)}</p>${source.binding ? `<p>Source artifact: ${h(source.binding.artifact_id)}. Snapshot: ${h(source.binding.snapshot_id ?? 'not supplied')}.</p>` : ''}<pre tabindex="0" aria-label="Exact attached source"><code>${h(source.text)}</code></pre></details>`).join('')}</section>
<details><summary>Package identity and omissions</summary><p>${h(context.artifact_id)}</p><p>${context.budget.used_bytes} UTF-8 bytes in the canonical JSON package. HTML has a different size.</p><pre tabindex="0" aria-label="Context omissions"><code>${h(JSON.stringify(context.omissions, null, 2))}</code></pre><p>${h(context.retrieval)}</p></details><p class="status">Scenario checks evaluate supplied observations. They do not prove the implementation or authenticate requirements.</p></main></body></html>\n`;
}

export function accountBytes<T extends { budget: ByteBudget }>(pack: T, requiredBytes = 0): T {
  for (let attempts = 0; attempts < 16; attempts++) {
    const size = Buffer.byteLength(compactJson(pack));
    if (size === pack.budget.used_bytes && (requiredBytes !== 0 || size === pack.budget.required_bytes)) return pack;
    pack.budget.used_bytes = size;
    pack.budget.required_bytes = requiredBytes || size;
  }
  throw new ClearingsError('CONTEXT_BUDGET', 'Byte accounting did not converge.');
}
